/* From Uiverse.io by Darlley - Tags: animation, media, input, audio */
.__UIV_SCOPE__ .audio.green-audio-player {
  width: 400px;
  min-width: 300px;
  height: 56px;
  box-shadow: 0 4px 16px 0 rgba(0, 0, 0, 0.07);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-left: 24px;
  padding-right: 24px;
  border-radius: 4px;
  user-select: none;
  -webkit-user-select: none;
  background-color: #fff;
}

.__UIV_SCOPE__ .audio.green-audio-player .play-pause-btn {
  cursor: pointer;
}

.__UIV_SCOPE__ .audio.green-audio-player .slider {
  flex-grow: 1;
  background-color: #d8d8d8;
  cursor: pointer;
  position: relative;
}

.__UIV_SCOPE__ .audio.green-audio-player .slider .progress {
  background-color: #44bfa3;
  border-radius: inherit;
  position: absolute;
  pointer-events: none;
}

.__UIV_SCOPE__ .audio.green-audio-player .slider .progress .pin {
  height: 16px;
  width: 16px;
  border-radius: 8px;
  background-color: #44bfa3;
  position: absolute;
  pointer-events: all;
  box-shadow: 0px 1px 1px 0px rgba(0, 0, 0, 0.32);
}

.__UIV_SCOPE__ .audio.green-audio-player .controls {
  font-family: "Roboto", sans-serif;
  font-size: 16px;
  line-height: 18px;
  color: #55606e;
  display: flex;
  flex-grow: 1;
  justify-content: space-between;
  align-items: center;
  margin-left: 24px;
  margin-right: 24px;
}

.__UIV_SCOPE__ .audio.green-audio-player .controls .slider {
  margin-left: 16px;
  margin-right: 16px;
  border-radius: 2px;
  height: 4px;
}

.__UIV_SCOPE__ .audio.green-audio-player .controls .slider .progress {
  width: 0;
  height: 100%;
}

.__UIV_SCOPE__ .audio.green-audio-player .controls .slider .pin {
  right: -8px;
  top: -6px;
}

.__UIV_SCOPE__ .audio.green-audio-player .controls span {
  cursor: default;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume {
  position: relative;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-btn {
  cursor: pointer;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-btn .open path {
  fill: #44bfa3;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-controls {
  width: 30px;
  height: 135px;
  background-color: rgba(0, 0, 0, 0.62);
  border-radius: 7px;
  position: absolute;
  left: -3px;
  bottom: 52px;
  flex-direction: column;
  align-items: center;
  display: flex;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-controls.hidden {
  display: none;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-controls .slider {
  margin-top: 12px;
  margin-bottom: 12px;
  width: 6px;
  border-radius: 3px;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-controls .slider .progress {
  bottom: 0;
  height: 100%;
  width: 6px;
}

.__UIV_SCOPE__ .audio.green-audio-player .volume .volume-controls .slider .progress .pin {
  left: -5px;
  top: -8px;
}
